def radix_sort(arr):
    RADIX = 10
    max_digit = max(arr)

    for digit in range(max_digit):
        buckets = [[] for _ in range(RADIX)]
        for num in arr:
            bucket[(num // (RADIX ** digit)) % RADIX].append(num)
        arr = []
        for bucket in buckets:
            arr.extend(bucket)
    return arr
