def min_coins(coins, m, V):
    # Initialize a list to store the minimum number of coins needed for each value up to V
    dp = [float('inf')] * (V + 1)

    # Base case: 0 coins are needed to make 0 value
    dp[0] = 0

    # Fill the dp array
    for i in range(1, V + 1):
        for coin in coins:
            if coin <= i:
                dp[i] = min(dp[i], dp[i - coin] + 1)

    return dp[V]
```

