def find_Max(arr, low, high):
    if high < low:
        return arr[low]
    mid = (high + low) // 2
    if mid < high and arr[mid+1] < arr[mid]:
        return arr[mid]
    if mid > low and arr[mid-1] > arr[mid]:
        return arr[mid]
    if arr[high] > arr[mid]:
        return find_Max(arr, low, mid-1)
    return find_Max(arr, mid+1, high)
